// Cross-engine check: replays duels generated by the authoritative C# engine (backend/tests/.../DuelFixtureTests.cs)
// and requires the identical event log, winner, LP and turn count.
import { describe, expect, it } from 'vitest';
import fixtures from './__fixtures__/duel-fixtures.json';
import { decide } from './ai';
import { apply, create } from './engine';
import { digest, finished, toAct, type DuelCard, type DuelRules } from './model';

const rules = fixtures.rules as unknown as DuelRules;

describe('TypeScript duel engine matches the C# engine', () => {
  for (const c of fixtures.cases) {
    it(`seed ${c.seed}: identical full AI-vs-AI duel`, () => {
      const decks = c.decks as unknown as DuelCard[][];
      const st = create(rules, { name: 'Blue', deck: decks[0] }, { name: 'Red', deck: decks[1] }, BigInt(c.seed));
      let n = 0;
      while (!finished(st) && n++ < 5000) apply(rules, st, toAct(st), decide(rules, st, toAct(st)));
      const got = st.log.map(digest);
      const firstDiff = got.findIndex((g, i) => g !== c.log[i]);
      expect(firstDiff === -1 ? null : { index: firstDiff, ts: got[firstDiff], cs: c.log[firstDiff] }).toBeNull();
      expect(got.length).toBe(c.log.length);
      expect(st.winner).toBe(c.winner);
      expect(st.endReason).toBe(c.endReason);
      expect(st.turn).toBe(c.turn);
      expect(st.players.map((p) => p.lp)).toEqual(c.lp);
    });
  }
});

describe('the rules shipped to the web preview are the server rules', () => {
  it('catalog.json duelRules equals the C# DuelRules (config, 33 tactics, skills, passives, elements)', async () => {
    const fsName = 'node:fs';
    const { readFileSync } = await import(/* @vite-ignore */ fsName) as { readFileSync: (f: string, e: string) => string };
    const cat = JSON.parse(readFileSync('public/data/catalog.json', 'utf8'));
    expect(cat.duelRules).toEqual(fixtures.rules);
    expect(Object.keys(cat.duelRules.tactics)).toHaveLength(33);
  });
});
